import {form,field,number as num,select as sel,text,area,result,outputText,e,n,error,download} from '../ui.mjs';
import {lineItems,wallPaint,settleTrip,zoneInstant,calendarICS} from './calc-core.mjs';
import {need,optional,today,localNow,table,exportCSV,textFile,printTools,localChoice} from './shared.mjs';
const currency=()=>sel('currency','Currency',['NPR','USD','EUR','GBP','INR','AUD'],'NPR');
const money=(amount,c)=>c+' '+Number(amount).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
export function setupLife(tool,mount,out){const id=tool.id,show=o=>result(out,o);if(['resume-builder','cover-letter','invoice-builder','quotation-builder'].includes(id))return documents(id,mount,out);if(id==='packing-checklist')return packing(mount,out);if(id==='birthday-countdown')return countdown(mount,out);
 const forms={
 'freelance-rate':()=>form(mount,[num('income','Desired annual income before tax',600000,0,1e12),num('expenses','Annual business expenses',100000,0,1e12),num('buffer','Reserve / contingency (%)',15,0,100),num('hours','Work hours per week',40,1,100),num('off','Weeks off per year',4,0,51,1),num('billable','Billable share of work time (%)',60,1,100),currency()],v=>{const hours=+v.hours*(52-+v.off)*+v.billable/100,budget=(+v.income+ +v.expenses)*(1+ +v.buffer/100),rate=budget/hours;show({label:'Planning rate per billable hour',value:money(rate,v.currency),details:[['Billable hours per year',n(hours)],['Annual revenue target',money(budget,v.currency)]],copy:money(rate,v.currency)+' / hour',note:'Taxes are not calculated. Include your own tax reserve in expenses or contingency as appropriate.'});},{label:'Estimate hourly rate'}),
 'paint-calculator':()=>form(mount,[num('length','Room length (m)',4,.1,100),num('width','Room width (m)',3,.1,100),num('height','Wall height (m)',2.8,.1,20),num('openings','Doors / windows area (m²)',4,0,10000),num('coats','Coats',2,1,10,1),num('coverage','Coverage (m² per liter per coat)',10,.1,100),num('waste','Extra allowance (%)',10,0,100),num('can','Can size (liters)',5,.1,100)],v=>{need(+v.openings<=2*(+v.length+ +v.width)*+v.height,'Opening area cannot exceed total wall area.');const r=wallPaint(+v.length,+v.width,+v.height,+v.openings,+v.coats,+v.coverage,+v.waste);show({label:'Estimated paint needed',value:n(r.liters)+' L',details:[['Net wall area',n(r.area)+' m²'],['Cans to buy',Math.ceil(r.liters/+v.can)],['Can size',v.can+' L']],copy:r.liters.toFixed(2)+' L; '+Math.ceil(r.liters/+v.can)+' cans',note:'Walls only; ceiling is excluded. Product coverage and surface condition affect actual use.'});},{label:'Estimate paint'}),
 'tile-calculator':()=>form(mount,[num('area','Area to cover (m²)',20,.01,100000),num('length','Tile length (cm)',60,.1,300),num('width','Tile width (cm)',60,.1,300),num('waste','Waste allowance (%)',10,0,100),num('perbox','Tiles per box',4,1,1000,1),num('price','Price per box',1500,0,1e8),currency()],v=>{const tile=+v.length*+v.width/10000,count=Math.ceil(+v.area*(1+ +v.waste/100)/tile),boxes=Math.ceil(count/+v.perbox);show({label:'Boxes needed',value:boxes,details:[['Tiles including allowance',count],['Purchased tiles',boxes*+v.perbox],['Tile area',n(tile)+' m²'],['Material cost',money(boxes*+v.price,v.currency)]],copy:`${boxes} boxes; ${count} tiles needed`,note:'Cut patterns, grout and laying design can change the quantity. Check your actual layout.'});},{label:'Estimate tiles & boxes'}),
 'concrete-volume':()=>form(mount,[sel('shape','Shape',[['slab','Slab / rectangular footing'],['cylinder','Cylinder']],'slab'),num('length','Length (m, rectangular)',5,.01,1000),num('width','Width (m, rectangular)',4,.01,1000),num('depth','Depth / height (m)',.12,.001,1000),num('diameter','Diameter (m, cylinder)',.4,.001,100),num('allowance','Extra allowance (%)',5,0,100)],v=>{const raw=v.shape==='slab'?+v.length*+v.width*+v.depth:Math.PI*(+v.diameter/2)**2*+v.depth,total=raw*(1+ +v.allowance/100);show({label:'Volume with allowance',value:n(total)+' m³',details:[['Geometric volume',n(raw)+' m³'],['Volume in liters',n(total*1000)+' L']],copy:total.toFixed(4)+' m³',note:'Volume only, not a structural specification or mix design. Only fields for the chosen shape apply.'});},{label:'Calculate concrete volume'}),
 'solar-energy':()=>form(mount,[num('kw','Panel capacity (kW)',3,.01,100000),num('sun','Peak sun hours per day',4,.1,12),num('ratio','Performance ratio (%)',80,1,100),num('days','Days in period',30,1,366,1)],v=>{const daily=+v.kw*+v.sun*+v.ratio/100;show({label:'Estimated energy for period',value:n(daily*+v.days)+' kWh',details:[['Daily output',n(daily)+' kWh'],['Entered days',v.days],['Formula','kW × peak sun hours × performance ratio']],copy:(daily*+v.days).toFixed(2)+' kWh',note:'All inputs are assumptions; no location, roof or shading data is fetched.'});},{label:'Estimate generation'}),
 'solar-payback':()=>form(mount,[num('cost','Installed system cost',300000,0,1e12),num('generation','Annual generation (kWh)',4000,0,1e9),num('self','Self-consumed generation (%)',80,0,100),num('tariff','Value per self-consumed kWh',10,0,1e5),num('export','Value per exported kWh',0,0,1e5),num('maintenance','Annual maintenance',2000,0,1e9),currency()],v=>{const benefit=+v.generation*(+v.self/100*+v.tariff+(1-+v.self/100)*+v.export)-+v.maintenance;show({label:'Simple payback',value:benefit>0?n(+v.cost/benefit)+' years':'No positive annual savings',details:[['Estimated net annual benefit',money(benefit,v.currency)],['Initial cost',money(+v.cost,v.currency)]],copy:benefit>0?(+v.cost/benefit).toFixed(2)+' years':'No positive annual savings',note:'Simple estimate excludes borrowing costs, degradation, future tariffs and time value of money.'});},{label:'Estimate simple payback'}),
 'meeting-planner':()=>form(mount,[text('local','Meeting date & time in source zone',today()+'T14:00','datetime-local',true),text('source','Source IANA time zone','Asia/Kathmandu','text',true),area('zones','Comparison zones — one per line','Europe/London\nAmerica/New_York\nAustralia/Sydney\nAsia/Seoul')],v=>{const instant=zoneInstant(v.local,v.source),zones=[v.source,...v.zones.split(/\n/).map(x=>x.trim()).filter(Boolean)];need(zones.length<=30,'Compare up to 30 zones.');const rows=[...new Set(zones)].map(zone=>[zone,new Intl.DateTimeFormat('en-GB',{timeZone:zone,dateStyle:'full',timeStyle:'short'}).format(instant.date)]);show({label:'Meeting instant (UTC)',value:instant.date.toISOString(),html:table(['Time zone','Local date and time'],rows),copy:rows.map(r=>r.join(': ')).join('\n'),note:instant.ambiguous?'This source time occurs twice during a clock change. This is one interpretation; choose an unambiguous time before scheduling.':'Offsets are calculated for this specific date using your browser’s time-zone data.'});},{label:'Compare time zones'}),
 'trip-settlement':()=>form(mount,[area('people','Name | amount paid — one per line','Nabi | 3000\nAarya | 1000\nMaya | 500'),currency()],v=>{const rows=v.people.trim().split(/\n/).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());need(a.length===2&&a[0]&&a[1]!==''&&Number.isFinite(+a[1])&&+a[1]>=0,'Use name | amount paid, with nonnegative amounts.');return{name:a[0],paid:+a[1]};});need(new Set(rows.map(r=>r.name)).size===rows.length,'Use unique names for each person.');const r=settleTrip(rows);show({label:'Equal share per person',value:money(r.share,v.currency),details:[['Total paid',money(r.total,v.currency)],['Rounding','Two decimal places; extra minor units assigned in input order']],html:r.transfers.length?table(['From','To','Amount'],r.transfers.map(x=>[x.from,x.to,money(x.amount,v.currency)])):'<p>Everyone is already settled.</p>',copy:r.transfers.map(x=>`${x.from} pays ${x.to}: ${money(x.amount,v.currency)}`).join('\n')});if(r.transfers.length)exportCSV(out,r.transfers,'nepocore-trip-settlement.csv');},{label:'Settle shared expenses'}),
 'calendar-invitation':()=>form(mount,[text('title','Event title','Project catch-up','text',true),text('start','Start date & time',today()+'T14:00','datetime-local'),text('end','End date & time',today()+'T15:00','datetime-local'),text('zone','IANA time zone','Asia/Kathmandu','text',true),optional(text('location','Location / meeting link','Online','text',true)),optional(area('description','Description','A quick project review.'))],v=>{const start=zoneInstant(v.start,v.zone),end=zoneInstant(v.end,v.zone);need(!start.ambiguous&&!end.ambiguous,'A selected time occurs twice during a clock change. Choose an unambiguous local time.');const ics=calendarICS({...v,start:start.date,end:end.date,uid:(globalThis.crypto.randomUUID?.()||Date.now()+'-'+Math.random())+'@nepocore'});textFile(out,ics,'nepocore-event.ics','text/calendar;charset=utf-8');},{label:'Create calendar file',note:'Downloads a calendar file. It does not send invitations or add events to a connected account.'}),
 'recipe-scaler':()=>form(mount,[num('original','Original servings',4,.1,10000),num('target','Target servings',6,.1,10000),area('ingredients','Ingredient | amount | unit','Flour | 200 | g\nMilk | 250 | mL\nEggs | 2 | whole')],v=>{const ratio=+v.target/+v.original,rows=v.ingredients.trim().split(/\n/).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());need(a.length===3&&a[0]&&a[1]!==''&&Number.isFinite(+a[1])&&+a[1]>=0,'Use ingredient | amount | unit.');return{name:a[0],amount:+a[1]*ratio,unit:a[2]};});need(rows.length<=100,'Use up to 100 ingredients.');show({label:'Scale factor',value:n(ratio)+'×',html:table(['Ingredient','Scaled amount','Unit'],rows.map(r=>[r.name,n(r.amount),r.unit])),copy:rows.map(r=>r.name+': '+n(r.amount)+' '+r.unit).join('\n'),note:'Amounts scale mathematically. Cooking time, pan size and fractional whole ingredients need your judgment.'});exportCSV(out,rows,'nepocore-scaled-recipe.csv');},{label:'Scale ingredients'}),
 'ingredient-cost':()=>form(mount,[area('ingredients','Ingredient | pack quantity | pack price | quantity used','Flour | 1000 | 120 | 200\nSugar | 1000 | 110 | 100'),currency()],v=>{const rows=v.ingredients.trim().split(/\n/).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());need(a.length===4&&a[0]&&a.slice(1).every(x=>x!==''&&Number.isFinite(+x)&&+x>=0)&&+a[1]>0,'Use ingredient | pack quantity | pack price | used quantity. Pack quantity must be positive.');return{name:a[0],packQuantity:+a[1],packPrice:+a[2],used:+a[3],cost:+a[2]/+a[1]*+a[3]};});need(rows.length<=100,'Use up to 100 rows.');show({label:'Ingredient cost',value:money(rows.reduce((s,r)=>s+r.cost,0),v.currency),html:table(['Ingredient','Used quantity','Cost'],rows.map(r=>[r.name,r.used,money(r.cost,v.currency)])),copy:JSON.stringify(rows,null,2),note:'Use matching units for pack and used quantity on each row; ingredient density is not inferred.'});exportCSV(out,rows,'nepocore-ingredient-cost.csv');},{label:'Calculate ingredient costs'}),
 'serving-cost':()=>form(mount,[num('ingredients','Batch ingredient cost',800,0,1e10),num('packaging','Batch packaging cost',80,0,1e10),num('overhead','Batch overhead allowance',120,0,1e10),num('servings','Number of servings',8,1,100000,1),num('margin','Chosen gross margin (%)',30,0,99),currency()],v=>{const total=+v.ingredients+ +v.packaging+ +v.overhead,cost=total/+v.servings;show({label:'Cost per serving',value:money(cost,v.currency),details:[['Total batch cost',money(total,v.currency)],['Price at chosen margin',money(cost/(1-+v.margin/100),v.currency)]],copy:money(cost,v.currency)+' cost per serving',note:'Margin is a share of the selling price, not a markup on cost. The estimate does not calculate taxes.'});},{label:'Calculate serving cost'}),
 'coffee-ratio':()=>form(mount,[sel('find','Find',[['coffee','Coffee amount'],['water','Water amount']],'coffee'),num('water','Water (g)',320,1,100000),num('coffee','Coffee (g)',20,.1,10000),num('ratio','Water parts for 1 part coffee',16,1,30,.1)],v=>{const r=v.find==='coffee'?+v.water/+v.ratio:+v.coffee*+v.ratio;show({label:v.find==='coffee'?'Coffee needed':'Water needed',value:n(r)+' g',details:[['Mass ratio','1:'+v.ratio]],copy:r.toFixed(2)+' g',note:'Only the known amount is used. The selected ratio is your brewing preference.'});},{label:'Calculate brew amounts'}),
 'oven-converter':()=>form(mount,[num('temperature','Recipe temperature',180,0,1000),sel('unit','Input scale',[['C','Celsius'],['F','Fahrenheit']],'C'),num('fan','Chosen fan reduction (°C)',20,0,50)],v=>{const c=v.unit==='C'?+v.temperature:(+v.temperature-32)*5/9;show({label:'Conventional oven',value:n(c)+' °C / '+n(c*9/5+32)+' °F',details:[['Fan-adjusted estimate',n(c-+v.fan)+' °C / '+n((c-+v.fan)*9/5+32)+' °F'],['Entered adjustment',v.fan+' °C reduction']],copy:`${c.toFixed(1)} °C / ${(c*9/5+32).toFixed(1)} °F`,note:'The fan adjustment is an entered approximation. Follow your oven and recipe guidance.'});},{label:'Convert oven settings'})
 };need(forms[id],'This everyday tool is unavailable.');forms[id]();}
function documents(id,mount,out){let release=()=>{};const common=[text('name',id==='resume-builder'?'Full name':'Your name / business','Nabin Kunwar','text',true),text('contact','Contact line','Kathmandu, Nepal · hello@example.com','text',true)];if(id==='resume-builder')form(mount,[...common,text('role','Headline','Web developer','text',true),area('summary','Profile','I build accessible, useful websites and enjoy learning new technologies.'),area('experience','Experience','Project developer — Nepocore\nBuilt browser tools with a focus on clarity and local processing.'),area('education','Education','Your qualification — Institution, year'),area('skills','Skills','JavaScript, HTML, CSS, Git, Linux')],v=>{const body=`<h1>${e(v.name)}</h1><p class="doc-muted">${e(v.role)}<br>${e(v.contact)}</p>${[['Profile',v.summary],['Experience',v.experience],['Education',v.education],['Skills',v.skills]].map(([label,value])=>`<h2>${label}</h2><p>${e(value)}</p>`).join('')}`;release();release=printTools(out,body,'Resume');},{label:'Build resume',note:'Replace example content with your own. Print / Save PDF uses your browser’s print dialog.'});else if(id==='cover-letter')form(mount,[...common,text('recipient','Recipient / hiring team','Hiring team','text',true),text('company','Organization','Example Company'),text('role','Role','Web developer'),text('date','Letter date',today(),'date'),area('opening','Opening','I am applying for the role because its focus aligns with my experience and interests.'),area('evidence','Your relevant experience','Describe a concrete project, contribution or skill relevant to this position.'),area('closing','Closing','Thank you for considering my application. I would welcome the opportunity to discuss how I can contribute.')],v=>{const body=`<h1>${e(v.name)}</h1><p class="doc-muted">${e(v.contact)}<br>${e(v.date)}</p><p>${e(v.recipient)}<br>${e(v.company)}</p><h2>Application: ${e(v.role)}</h2><p>Dear ${e(v.recipient)},</p><p>${e(v.opening)}</p><p>${e(v.evidence)}</p><p>${e(v.closing)}</p><p>Sincerely,<br>${e(v.name)}</p>`;release();release=printTools(out,body,'Cover Letter');},{label:'Build editable letter'});else{const quote=id==='quotation-builder';form(mount,[...common,text('client','Client name / details','Example Client','text',true),text('number',quote?'Quote number':'Invoice number',quote?'QUO-001':'INV-001'),text('date','Issue date',today(),'date'),text('due',quote?'Valid until':'Due date',today(),'date'),area('items','Description | quantity | unit price','Design work | 1 | 5000\nDevelopment | 5 | 1000'),num('discount','Discount (%)',0,0,100),num('tax','Tax (%)',0,0,100),currency(),optional(area('terms','Notes / terms',quote?'Scope and price are subject to agreement.':'Thank you for your business.'))],v=>{const rows=lineItems(v.items);need(rows.length<=100,'Use up to 100 line items.');const subtotal=rows.reduce((s,r)=>s+r.amount,0),discount=subtotal*+v.discount/100,tax=(subtotal-discount)*+v.tax/100,total=subtotal-discount+tax,body=`<div class="doc-top"><div><h1>${quote?'Quotation':'Invoice'}</h1><p>${e(v.name)}<br>${e(v.contact)}</p></div><p>${e(v.number)}<br>Issued: ${e(v.date)}<br>${quote?'Valid until':'Due'}: ${e(v.due)}</p></div><h2>${quote?'Prepared for':'Bill to'}</h2><p>${e(v.client)}</p>${table(['Description','Qty','Unit price','Amount'],rows.map(r=>[r.name,n(r.quantity),money(r.price,v.currency),money(r.amount,v.currency)]))}<p class="doc-total">Subtotal: ${money(subtotal,v.currency)}<br>Discount: ${money(discount,v.currency)}<br>Tax: ${money(tax,v.currency)}<br><strong>Total: ${money(total,v.currency)}</strong></p><h2>Notes / terms</h2><p>${e(v.terms)}</p>`;release();release=printTools(out,body,quote?'Quotation':'Invoice');},{label:quote?'Build quotation':'Build invoice',note:'Currency and tax are your inputs; legal and local tax requirements are not inferred.'});}return()=>release();}
function packing(mount,out){const starters={essentials:['Travel documents','Wallet / payment cards','Phone and charger','Essential personal items','Clothing','Toiletries','Water bottle'],beach:['Swimwear','Sun protection','Towel','Hat','Sandals'],business:['Laptop and charger','Work documents','Meeting clothes','Adapter','Notebook'],hike:['Route / offline map','Suitable footwear','Layers and rain cover','Food and water','First-aid supplies']};let items=starters.essentials.map(name=>({name,checked:false}));mount.innerHTML='<h2>Pack a little more calmly</h2><label class="field"><span>Add a starter set</span><select data-template><option value="essentials">Essentials</option><option value="beach">Beach</option><option value="business">Business</option><option value="hike">Hiking</option></select></label><button class="btn secondary small" data-add-set>Add starter items</button><form class="inline-form"><label class="field"><span>Custom item</span><input name="item" required maxlength="120"></label><button class="btn primary small" type="submit">Add item</button></form><div class="packing-items"></div><button class="btn secondary small" data-clear-checks>Uncheck all</button>';let persist=()=>{};function render(){const list=mount.querySelector('.packing-items');list.replaceChildren();items.forEach((item,i)=>{const row=document.createElement('div');row.className='check-row';row.innerHTML=`<label><input type="checkbox" ${item.checked?'checked':''}><span>${e(item.name)}</span></label><button type="button" aria-label="Remove ${e(item.name)}">×</button>`;row.querySelector('input').onchange=ev=>{item.checked=ev.target.checked;persist();summary();};row.querySelector('button').onclick=()=>{items.splice(i,1);persist();render();};list.append(row);});summary();}function summary(){const value=items.map(x=>(x.checked?'[x] ':'[ ] ')+x.name).join('\n');textFile(out,value,'nepocore-packing-list.txt');}mount.querySelector('form').onsubmit=ev=>{ev.preventDefault();const input=ev.currentTarget.elements.item;if(!input.value.trim()||items.length>=200)return;items.push({name:input.value.trim(),checked:false});input.value='';persist();render();};mount.querySelector('[data-add-set]').onclick=()=>{for(const name of starters[mount.querySelector('[data-template]').value])if(!items.some(x=>x.name===name))items.push({name,checked:false});persist();render();};mount.querySelector('[data-clear-checks]').onclick=()=>{items.forEach(x=>x.checked=false);persist();render();};render();persist=localChoice(mount,'nepocore-packing-v1',saved=>{if(Array.isArray(saved)&&saved.length<=200&&saved.every(x=>typeof x.name==='string'&&typeof x.checked==='boolean')){items=saved;render();}},()=>items);return()=>persist();}
function countdown(mount,out){let timer;form(mount,[text('name','Name / event','A special birthday','text',true),sel('mode','Countdown type',[['birthday','Next birthday — repeats yearly'],['event','One-time event date']],'birthday'),text('date','Birthday or event date','2000-10-31','date'),sel('leap','February 29 in non-leap years',[['feb28','Use February 28'],['mar1','Use March 1']],'feb28')],v=>{clearInterval(timer);const source=new Date(v.date+'T12:00:00'),now=new Date();let target;if(v.mode==='event')target=new Date(v.date+'T00:00:00');else{const get=y=>{const leap=new Date(y,1,29).getMonth()===1;if(source.getMonth()===1&&source.getDate()===29&&!leap)return v.leap==='feb28'?new Date(y,1,28):new Date(y,2,1);return new Date(y,source.getMonth(),source.getDate());};target=get(now.getFullYear());if(target<=now)target=get(now.getFullYear()+1);}need(Number.isFinite(+target),'Choose a valid date.');function value(){let s=Math.max(0,Math.floor((target-Date.now())/1000)),days=Math.floor(s/86400);s%=86400;return{days,hours:Math.floor(s/3600),minutes:Math.floor(s/60)%60,seconds:s%60};}const r=value();result(out,{label:v.name,value:r.days+' days',html:'<div class="countdown-detail" aria-live="off"></div>',details:[['Target date',target.toLocaleDateString()],['Timezone',Intl.DateTimeFormat().resolvedOptions().timeZone]],copy:v.name+': '+target.toLocaleDateString(),note:+target<Date.now()?'This event date has passed.':'Countdown uses this device’s clock and local timezone.'});const d=out.querySelector('.countdown-detail');const update=()=>{const r=value();d.textContent=r.hours+'h '+r.minutes+'m '+r.seconds+'s';};update();timer=setInterval(update,1000);const b=document.createElement('button');b.className='btn secondary small';b.textContent='Download countdown card';b.onclick=async()=>{const {canvas,canvasBlob}=await import('../media.mjs');const c=canvas(1080,1080),x=c.getContext('2d');x.fillStyle='#f3eee9';x.fillRect(0,0,1080,1080);x.fillStyle='#28594d';x.textAlign='center';x.font='40px Georgia';x.fillText(v.name.slice(0,70),540,260,920);x.font='bold 160px sans-serif';x.fillText(String(value().days),540,550);x.font='40px sans-serif';x.fillText('days to go',540,640);x.font='24px sans-serif';x.fillText(target.toLocaleDateString(),540,760);x.font='18px sans-serif';x.fillText('Made with Nepocore',540,1000);download(await canvasBlob(c),'nepocore-countdown.png');};out.querySelector('.result-actions').append(b);},{label:'Start countdown'});return()=>clearInterval(timer);}
